declare item jsonb;p pg_catalog.pg_proc%rowtype;source text;statements text[]:=array[]::text[];ddl text;
 manifest jsonb:=$budget_required_patches$[{"signature":"public.claim_canonical_rewrite_dispatch(uuid,uuid,uuid,text,jsonb)","before":"77a9357fde10413f08d0276bae3c1b747f44e2de10c1ef757d47eb05b21992aa","after":"08c3eedd3979e2a3287d5ab8dac9da876daa7c18ad5fdd848661c54949f1aa66","old":"\ndeclare a public.analyses%rowtype; op private.canonical_rewrite_operations%rowtype; ctx jsonb; budget jsonb;\nbegin\n  a:=private.canonical_rewrite_owner(p_user_id,p_analysis_id);\n  select * into strict op from private.canonical_rewrite_operations where owner_id=p_user_id and analysis_id=p_analysis_id and operation_id=p_operation_id for update;\n  if op.binding_sha256 is distinct from p_binding_sha256 or op.organization_id is distinct from a.organization_id then perform private.correction_fail('conflict'); end if;\n  if op.state<>'reserved' then return jsonb_build_object('operation',private.canonical_rewrite_operation(op,false),'budget',null); end if;\n  if private.canonical_rewrite_ready() is not true then perform private.correction_fail('unavailable'); end if;\n  perform private.canonical_rewrite_consent(p_user_id,a.organization_id);\n  ctx:=public.read_canonical_rewrite_context(p_user_id,p_analysis_id,jsonb_build_object('canonicalVersionId',op.request->'canonicalVersionId','requirementVersionId',op.request->'requirementVersionId'),op.policy);\n  if ctx->>'bindingSha256' is distinct from op.binding_sha256\n    or ctx->'relationshipContext'->'heads'->'canonicalHeadId' is distinct from op.request->'canonicalVersionId'\n    or ctx->'relationshipContext'->'heads'->'requirementHeadId' is distinct from op.request->'requirementVersionId' then perform private.correction_fail('conflict'); end if;\n  if p_budget is not null and p_budget<>'null'::jsonb then\n    if private.evidence_keys(p_budget,array['p_user_id','p_organization_id','p_request']) is not true\n      or p_budget->>'p_user_id' is distinct from p_user_id::text or p_budget->>'p_organization_id' is distinct from a.organization_id::text\n      or p_budget->'p_request'->>'operationId' is distinct from private.ai_budget_source_identity(p_user_id,a.organization_id,'canonical_rewrite',p_analysis_id,op.source_id,p_operation_id::text)::text\n      or p_budget->'p_request'->>'surface' is distinct from 'rewrite'\n      or p_budget->'p_request'->>'model' is distinct from op.policy->>'model'\n      or p_budget->'p_request'->>'promptPolicyVersion' is distinct from op.policy->>'promptVersion'\n      or p_budget->'p_request'->>'payloadSha256' is distinct from op.binding_sha256 then perform private.correction_fail('invalid'); end if;\n    if not exists(select 1 from private.ai_budget_operation_sources s where s.operation_id=(p_budget->'p_request'->>'operationId')::uuid and s.kind='canonical_rewrite'\n      and (s.owner_id,s.organization_id,s.analysis_id,s.resume_version_id,s.request_nonce)=(p_user_id,a.organization_id,p_analysis_id,op.source_id,p_operation_id::text)) then perform private.correction_fail('invalid');end if;\n    budget:=private.ai_budget_transition(p_user_id,a.organization_id,p_budget->'p_request','claim_dispatch');\n    -- A denied/replayed budget claim must roll back the operation claim as well.\n    if budget->>'status' is distinct from 'ok' or budget->'receipt'->'dispatchAllowed' is distinct from 'true'::jsonb then\n      return jsonb_build_object('operation',private.canonical_rewrite_operation(op,false),'budget',budget); end if;\n  end if;\n  update private.canonical_rewrite_operations set state='dispatched',claimed_at=clock_timestamp()\n    where owner_id=p_user_id and analysis_id=p_analysis_id and operation_id=p_operation_id returning * into op;\n  return jsonb_build_object('operation',private.canonical_rewrite_operation(op,true),'budget',budget);\nend;\n","new":"\ndeclare a public.analyses%rowtype; op private.canonical_rewrite_operations%rowtype; ctx jsonb; budget jsonb;\nbegin\n  a:=private.canonical_rewrite_owner(p_user_id,p_analysis_id);\n  select * into strict op from private.canonical_rewrite_operations where owner_id=p_user_id and analysis_id=p_analysis_id and operation_id=p_operation_id for update;\n  if op.binding_sha256 is distinct from p_binding_sha256 or op.organization_id is distinct from a.organization_id then perform private.correction_fail('conflict'); end if;\n  if op.state<>'reserved' then return jsonb_build_object('operation',private.canonical_rewrite_operation(op,false),'budget',null); end if;\n  if p_budget is null or p_budget='null'::jsonb then perform private.correction_fail('unavailable');end if;\n  if private.canonical_rewrite_ready() is not true then perform private.correction_fail('unavailable'); end if;\n  perform private.canonical_rewrite_consent(p_user_id,a.organization_id);\n  ctx:=public.read_canonical_rewrite_context(p_user_id,p_analysis_id,jsonb_build_object('canonicalVersionId',op.request->'canonicalVersionId','requirementVersionId',op.request->'requirementVersionId'),op.policy);\n  if ctx->>'bindingSha256' is distinct from op.binding_sha256\n    or ctx->'relationshipContext'->'heads'->'canonicalHeadId' is distinct from op.request->'canonicalVersionId'\n    or ctx->'relationshipContext'->'heads'->'requirementHeadId' is distinct from op.request->'requirementVersionId' then perform private.correction_fail('conflict'); end if;\n  if p_budget is not null and p_budget<>'null'::jsonb then\n    if private.evidence_keys(p_budget,array['p_user_id','p_organization_id','p_request']) is not true\n      or p_budget->>'p_user_id' is distinct from p_user_id::text or p_budget->>'p_organization_id' is distinct from a.organization_id::text\n      or p_budget->'p_request'->>'operationId' is distinct from private.ai_budget_source_identity(p_user_id,a.organization_id,'canonical_rewrite',p_analysis_id,op.source_id,p_operation_id::text)::text\n      or p_budget->'p_request'->>'surface' is distinct from 'rewrite'\n      or p_budget->'p_request'->>'model' is distinct from op.policy->>'model'\n      or p_budget->'p_request'->>'promptPolicyVersion' is distinct from op.policy->>'promptVersion'\n      or p_budget->'p_request'->>'payloadSha256' is distinct from op.binding_sha256 then perform private.correction_fail('invalid'); end if;\n    if not exists(select 1 from private.ai_budget_operation_sources s where s.operation_id=(p_budget->'p_request'->>'operationId')::uuid and s.kind='canonical_rewrite'\n      and (s.owner_id,s.organization_id,s.analysis_id,s.resume_version_id,s.request_nonce)=(p_user_id,a.organization_id,p_analysis_id,op.source_id,p_operation_id::text)) then perform private.correction_fail('invalid');end if;\n    budget:=private.ai_budget_transition(p_user_id,a.organization_id,p_budget->'p_request','claim_dispatch');\n    -- A denied/replayed budget claim must roll back the operation claim as well.\n    if budget->>'status' is distinct from 'ok' or budget->'receipt'->'dispatchAllowed' is distinct from 'true'::jsonb then\n      return jsonb_build_object('operation',private.canonical_rewrite_operation(op,false),'budget',budget); end if;\n  end if;\n  update private.canonical_rewrite_operations set state='dispatched',claimed_at=clock_timestamp()\n    where owner_id=p_user_id and analysis_id=p_analysis_id and operation_id=p_operation_id returning * into op;\n  return jsonb_build_object('operation',private.canonical_rewrite_operation(op,true),'budget',budget);\nend;\n"},{"signature":"public.claim_initial_feedback_dispatch(uuid,jsonb,uuid,uuid,text,jsonb)","before":"8d9ca0645d4457616d6a7fc947658fa89b3b7529042ba6f17f90f1cbc051012a","after":"f7b45e9f59df53aa5324c6a62b2d800201c2d27b29eac5f76b3bc5a59c3f50a5","old":"\ndeclare a public.analyses%rowtype;op private.initial_feedback_operations%rowtype;att private.initial_feedback_attempts%rowtype;\n  original jsonb;ctx jsonb;pol jsonb;budget jsonb:=null;req jsonb;\nbegin\n  if p_analysis_id is null or p_operation_id is null or p_attempt_id is null or p_binding_sha256 is null\n    or p_binding_sha256 collate \"C\" !~ '^[a-f0-9]{64}$' or private.legacy_scoring_lease(p_lease) is not true then perform private.ifo_fail('invalid');end if;\n  if private.initial_feedback_operation_ready() is not true then perform private.ifo_fail('unavailable');end if;\n  a:=private.legacy_scoring_access(p_analysis_id,null);original:=private.ifo_original(a);\n  select * into op from private.initial_feedback_operations where operation_id=p_operation_id and analysis_id=a.id\n    and owner_id=a.owner_id and organization_id=a.organization_id for update;\n  if not found or op.binding_sha256<>p_binding_sha256\n    or op.binding is distinct from private.ifo_binding(original,op.binding->'policy') then perform private.ifo_fail('not_found');end if;\n  select * into att from private.initial_feedback_attempts where attempt_id=p_attempt_id and operation_id=op.operation_id for update;\n  if not found then perform private.ifo_fail('not_found');end if;\n  if private.legacy_scoring_static_job(a.id,p_lease) is not true and att.claim_lease is distinct from p_lease then perform private.ifo_fail('not_found');end if;\n  if op.state<>'open' or op.publication_id is not null or att.state<>'reserved' then\n    return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),\n      'dispatchAllowed',false,'replayed',true,'budget',null);\n  end if;\n  if a.status<>'qualitative_review' or not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)\n    then perform private.ifo_fail('stale');end if;\n  pol:=private.ifo_selected_policy(a.organization_id,jsonb_build_object('version',op.policy_version,'sha256',op.policy_sha256));\n  if pol is distinct from op.binding->'policy' then perform private.ifo_fail('stale');end if;\n  ctx:=private.ifo_context(a,original);\n  if ctx->>'generationEligibility'<>'eligible' or private.ifo_binding(ctx,pol) is distinct from op.binding then perform private.ifo_fail('stale');end if;\n  -- The actual frozen source parser checks its source-domain/resource limits\n  -- BEFORE any provider permission; it supplies no candidate qualification.\n  perform private.ifp_document(ctx->'scoringContext'->'extraction'->>'text');\n  perform 1 from public.consents where user_id=a.owner_id and purpose='qualitative_ai' and policy_version='candidate-ai-v1' for share skip locked;\n  if not found then perform private.ifo_fail('not_found');end if;\n  if pol->'budgetPolicyVersion'='null'::jsonb then\n    if p_budget is not null and p_budget<>'null'::jsonb then perform private.ifo_fail('invalid');end if;\n  else\n    if private.ifo_keys(p_budget,array['p_user_id','p_organization_id','p_request']) is not true\n      or p_budget->>'p_user_id' is distinct from a.owner_id::text or p_budget->>'p_organization_id' is distinct from a.organization_id::text\n      then perform private.ifo_fail('invalid');end if;\n    req:=p_budget->'p_request';\n    if private.ai_budget_request_valid(req,'claim_dispatch') is not true or req->>'operationId' is distinct from op.operation_id::text\n      or req->>'attemptId' is distinct from att.attempt_id::text or (req->>'attemptOrdinal')::numeric is distinct from att.ordinal::numeric\n      or req->>'surface' is distinct from 'qualitative' or req->>'model' is distinct from pol->>'model'\n      or req->>'promptPolicyVersion' is distinct from pol->>'promptVersion' or req->>'policyVersion' is distinct from pol->>'budgetPolicyVersion'\n      or req->>'payloadSha256' is distinct from op.binding_sha256\n      or (req->>'reservedOutputTokens')::numeric is distinct from (pol->>'maxOutputTokens')::numeric then perform private.ifo_fail('invalid');end if;\n    -- Never wait for the inverse org -> membership order of generic R03 while\n    -- already holding analysis/queue/source/membership locks. Reentrant after.\n    perform 1 from public.organizations where id=a.organization_id for update skip locked;\n    if not found then perform private.ifo_fail('stale');end if;\n    perform 1 from public.memberships where organization_id=a.organization_id and user_id=a.owner_id\n      and role in ('owner','admin','member') for update skip locked;\n    if not found then perform private.ifo_fail('stale');end if;\n    if not exists(select 1 from private.ai_budget_operation_sources s where s.kind='initial_feedback' and (s.operation_id,s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id)\n      =(op.operation_id,a.owner_id,a.organization_id,a.id,op.resume_id,op.resume_version_id)) then perform private.ifo_fail('invalid');end if;\n    budget:=private.ai_budget_transition(a.owner_id,a.organization_id,req,'claim_dispatch');\n    if budget->>'status'='denied' then\n      return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),\n        'dispatchAllowed',false,'replayed',false,'budget',budget);\n    end if;\n    -- An existing generic winner cannot be adopted as this still-reserved\n    -- feedback attempt. Never mark/release that winner or dispatch a new one.\n    if budget->>'status' is distinct from 'ok' or budget->'receipt'->'dispatchAllowed' is distinct from 'true'::jsonb then perform private.ifo_fail('stale');end if;\n    if budget->'receipt'->>'attemptId' is distinct from att.attempt_id::text or budget->'receipt'->>'operationId' is distinct from op.operation_id::text\n      or budget->'receipt'->'replayed' is distinct from 'false'::jsonb then perform private.ifo_fail('stale');end if;\n  end if;\n  if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)\n    or private.try_candidate_privacy_write(a.owner_id) is not true then perform private.ifo_fail('stale');end if;\n  update private.initial_feedback_attempts set state='dispatched',claim_lease=p_lease,claimed_at=clock_timestamp(),\n    budget_attempt_id=case when budget is null then null else att.attempt_id end\n    where attempt_id=att.attempt_id and state='reserved' returning * into att;\n  if not found then perform private.ifo_fail('stale');end if;\n  return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),\n    'dispatchAllowed',true,'replayed',false,'budget',budget);\nend;\n","new":"\ndeclare a public.analyses%rowtype;op private.initial_feedback_operations%rowtype;att private.initial_feedback_attempts%rowtype;\n  original jsonb;ctx jsonb;pol jsonb;budget jsonb:=null;req jsonb;\nbegin\n  if p_analysis_id is null or p_operation_id is null or p_attempt_id is null or p_binding_sha256 is null\n    or p_binding_sha256 collate \"C\" !~ '^[a-f0-9]{64}$' or private.legacy_scoring_lease(p_lease) is not true then perform private.ifo_fail('invalid');end if;\n  if private.initial_feedback_operation_ready() is not true then perform private.ifo_fail('unavailable');end if;\n  a:=private.legacy_scoring_access(p_analysis_id,null);original:=private.ifo_original(a);\n  select * into op from private.initial_feedback_operations where operation_id=p_operation_id and analysis_id=a.id\n    and owner_id=a.owner_id and organization_id=a.organization_id for update;\n  if not found or op.binding_sha256<>p_binding_sha256\n    or op.binding is distinct from private.ifo_binding(original,op.binding->'policy') then perform private.ifo_fail('not_found');end if;\n  select * into att from private.initial_feedback_attempts where attempt_id=p_attempt_id and operation_id=op.operation_id for update;\n  if not found then perform private.ifo_fail('not_found');end if;\n  if private.legacy_scoring_static_job(a.id,p_lease) is not true and att.claim_lease is distinct from p_lease then perform private.ifo_fail('not_found');end if;\n  if op.state<>'open' or op.publication_id is not null or att.state<>'reserved' then\n    return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),\n      'dispatchAllowed',false,'replayed',true,'budget',null);\n  end if;\n  if (op.binding->'policy'->>'budgetPolicyVersion') is null or p_budget is null or p_budget='null'::jsonb then perform private.ifo_fail('unavailable');end if;\n  if a.status<>'qualitative_review' or not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)\n    then perform private.ifo_fail('stale');end if;\n  pol:=private.ifo_selected_policy(a.organization_id,jsonb_build_object('version',op.policy_version,'sha256',op.policy_sha256));\n  if pol is distinct from op.binding->'policy' then perform private.ifo_fail('stale');end if;\n  ctx:=private.ifo_context(a,original);\n  if ctx->>'generationEligibility'<>'eligible' or private.ifo_binding(ctx,pol) is distinct from op.binding then perform private.ifo_fail('stale');end if;\n  -- The actual frozen source parser checks its source-domain/resource limits\n  -- BEFORE any provider permission; it supplies no candidate qualification.\n  perform private.ifp_document(ctx->'scoringContext'->'extraction'->>'text');\n  perform 1 from public.consents where user_id=a.owner_id and purpose='qualitative_ai' and policy_version='candidate-ai-v1' for share skip locked;\n  if not found then perform private.ifo_fail('not_found');end if;\n  if pol->'budgetPolicyVersion'='null'::jsonb then\n    if p_budget is not null and p_budget<>'null'::jsonb then perform private.ifo_fail('invalid');end if;\n  else\n    if private.ifo_keys(p_budget,array['p_user_id','p_organization_id','p_request']) is not true\n      or p_budget->>'p_user_id' is distinct from a.owner_id::text or p_budget->>'p_organization_id' is distinct from a.organization_id::text\n      then perform private.ifo_fail('invalid');end if;\n    req:=p_budget->'p_request';\n    if private.ai_budget_request_valid(req,'claim_dispatch') is not true or req->>'operationId' is distinct from op.operation_id::text\n      or req->>'attemptId' is distinct from att.attempt_id::text or (req->>'attemptOrdinal')::numeric is distinct from att.ordinal::numeric\n      or req->>'surface' is distinct from 'qualitative' or req->>'model' is distinct from pol->>'model'\n      or req->>'promptPolicyVersion' is distinct from pol->>'promptVersion' or req->>'policyVersion' is distinct from pol->>'budgetPolicyVersion'\n      or req->>'payloadSha256' is distinct from op.binding_sha256\n      or (req->>'reservedOutputTokens')::numeric is distinct from (pol->>'maxOutputTokens')::numeric then perform private.ifo_fail('invalid');end if;\n    -- Never wait for the inverse org -> membership order of generic R03 while\n    -- already holding analysis/queue/source/membership locks. Reentrant after.\n    perform 1 from public.organizations where id=a.organization_id for update skip locked;\n    if not found then perform private.ifo_fail('stale');end if;\n    perform 1 from public.memberships where organization_id=a.organization_id and user_id=a.owner_id\n      and role in ('owner','admin','member') for update skip locked;\n    if not found then perform private.ifo_fail('stale');end if;\n    if not exists(select 1 from private.ai_budget_operation_sources s where s.kind='initial_feedback' and (s.operation_id,s.owner_id,s.organization_id,s.analysis_id,s.resume_id,s.resume_version_id)\n      =(op.operation_id,a.owner_id,a.organization_id,a.id,op.resume_id,op.resume_version_id)) then perform private.ifo_fail('invalid');end if;\n    budget:=private.ai_budget_transition(a.owner_id,a.organization_id,req,'claim_dispatch');\n    if budget->>'status'='denied' then\n      return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),\n        'dispatchAllowed',false,'replayed',false,'budget',budget);\n    end if;\n    -- An existing generic winner cannot be adopted as this still-reserved\n    -- feedback attempt. Never mark/release that winner or dispatch a new one.\n    if budget->>'status' is distinct from 'ok' or budget->'receipt'->'dispatchAllowed' is distinct from 'true'::jsonb then perform private.ifo_fail('stale');end if;\n    if budget->'receipt'->>'attemptId' is distinct from att.attempt_id::text or budget->'receipt'->>'operationId' is distinct from op.operation_id::text\n      or budget->'receipt'->'replayed' is distinct from 'false'::jsonb then perform private.ifo_fail('stale');end if;\n  end if;\n  if not private.lock_analysis_stage_lease(a.id,p_lease->>'workerId',(p_lease->>'attempt')::integer,(p_lease->>'leaseFence')::uuid)\n    or private.try_candidate_privacy_write(a.owner_id) is not true then perform private.ifo_fail('stale');end if;\n  update private.initial_feedback_attempts set state='dispatched',claim_lease=p_lease,claimed_at=clock_timestamp(),\n    budget_attempt_id=case when budget is null then null else att.attempt_id end\n    where attempt_id=att.attempt_id and state='reserved' returning * into att;\n  if not found then perform private.ifo_fail('stale');end if;\n  return jsonb_build_object('schemaVersion','initial-feedback-claim/1.0.0','operation',private.ifo_operation_json(op),'attempt',private.ifo_attempt_json(att),\n    'dispatchAllowed',true,'replayed',false,'budget',budget);\nend;\n"},{"signature":"private.canonical_rewrite_ready()","before":"ef084481faf7a75e5da4dafbabdb8cd9c2aacae542b26c5e90ced4ed25b8ef14","after":"b8f2c321599054fc5a05bdccdd15ebd8b3bd3bbdc8e7cf233c99cc01b205ffed","old":"\ndeclare routine pg_catalog.pg_proc%rowtype; predecessor pg_catalog.pg_proc%rowtype; rel pg_catalog.pg_class%rowtype;\n  target jsonb; role_name text; name text; service_oid oid:=(select oid from pg_catalog.pg_roles where rolname='service_role');\n  manifest jsonb:=$cr_catalog$[\n  {\n    \"signature\": \"private.canonical_rewrite_immutable()\",\n    \"sha256\": \"c9112879a49deae16f5714cd898b7ab7a960e532a126f0227d443f4fecebfb1d\",\n 